        'tenant_created_paid' => 'கட்டணம் உறுதிசெய்யப்பட்ட நிலையில் குத்தகைதாரர் உருவாக்கப்பட்டது. பணியிடத்தை உருவாக்க அங்கீகரிக்கவும்.',
        'tenant_created_pending' => 'நிலுவை நிலையில் குத்தகைதாரர் உருவாக்கப்பட்டது. பணியிடத்தை உருவாக்க அங்கீகரிக்கவும்.',
