        'tenant_payment_first' => 'அங்கீகரிக்கும் முன் கட்டணம் உறுதிசெய்யப்பட வேண்டும். முதலில் கட்டணத்தை செலுத்தப்பட்டதாகக் குறிக்கவும்.',
        'tenant_approved' => 'குத்தகைதாரர் அங்கீகரிக்கப்பட்டார். உருவாக்கம் தொடங்கியது — முன்னேற்றத்தைச் சரிபார்க்க இந்தப் பக்கத்தைப் புதுப்பிக்கவும்.',
        'tenant_rejected' => 'குத்தகைதாரர் நிராகரிக்கப்பட்டு தெரிவிக்கப்பட்டார்.',
        'tenant_reprovision' => 'மறுஉருவாக்கம் தொடங்கியது. பக்கம் "உருவாக்கப்படுகிறது" நிலையைக் காட்டும் — முடிந்ததா எனச் சரிபார்க்க புதுப்பிக்கவும்.',
        'db_none_configured' => 'இந்தக் குத்தகைதாரருக்கு தரவுத்தளம் எதுவும் உள்ளமைக்கப்படவில்லை.',
        'db_no_credentials' => 'இந்தக் குத்தகைதாரருக்கு தரவுத்தள நற்சான்றுகள் எதுவும் உள்ளமைக்கப்படவில்லை.',
