        'db_cannot_connect_server' => 'குத்தகைதாரர் தரவுத்தள சேவையகத்துடன் இணைக்க முடியவில்லை: :error',
        'db_creds_saved_failed' => 'நற்சான்றுகள் சேமிக்கப்பட்டன ஆனால் இணைப்பு தோல்வியடைந்தது: :error',
        'db_creds_verified' => 'தரவுத்தள நற்சான்றுகள் புதுப்பிக்கப்பட்டு இணைப்பு சரிபார்க்கப்பட்டது.',
        'db_migrations_ok' => 'மைக்ரேஷன்கள் வெற்றிகரமாக மீண்டும் இயக்கப்பட்டன.',
