            'xero' => 'Xero கணக்கியல் ஒத்திசைவு: தொடர்புகள், விலைப்பட்டியல்கள் மற்றும் கட்டணங்கள்',
            'prestashop' => 'PrestaShop கடை ஒத்திசைவு: பொருட்கள், இருப்பு மற்றும் ஆர்டர்கள்',
            'google_sheets' => 'Google Sheets ஏற்றுமதிகள்: விற்பனை, பொருட்கள் மற்றும் வாடிக்கையாளர்கள்',
            'mailchimp' => 'மின்னஞ்சல் சந்தைப்படுத்தலுக்கான Mailchimp பார்வையாளர் ஒத்திசைவு',
