            'fleet' => 'வாகனங்கள், பராமரிப்பு, எரிபொருள் பதிவுகள் மற்றும் ஓட்டுநர் ஒதுக்கீடுகள்',
            'hospital' => 'நோயாளிகள், சந்திப்புகள், ஆலோசனைகள், அனுமதிகள், ஆய்வகம் மற்றும் பில்லிங்',
            'school' => 'மாணவர்கள், சேர்க்கை, வருகை, கால அட்டவணை, தேர்வுகள் மற்றும் கட்டணங்கள்',
            'protocol' => 'உள் செய்தியிடல், புகார்கள், குறிப்பாணைகள் மற்றும் மேசையிலிருந்து மேசைக்கான கோரிக்கை கண்காணிப்பு',
