            'rental' => 'வாடகைப் பொருட்கள், ஒப்பந்தங்கள், முன்பதிவுகள், விலைப்பட்டியல், வைப்புத்தொகைகள், ஒப்படைப்புகள் மற்றும் பராமரிப்பு',
            'crm' => 'லீட்கள், டீல்கள் பைப்லைன், செயல்பாடுகள், வலைப் படிவங்கள், இன்பாக்ஸ், இலக்குகள் மற்றும் விற்பனை அறிக்கைகள்',
