        'show_site_name_hint' => 'பக்கப்பட்டி மற்றும் முகப்புப் பக்கத்தில் பிராண்ட் லோகோவுக்கு அருகில் செயலிப் பெயரைக் காட்டவும்.',
        'dashboard_footer_text' => 'டாஷ்போர்டு அடிக்குறிப்பு உரை',
        'dashboard_footer_text_hint' => 'ஒவ்வொரு சூப்பர் நிர்வாகி பக்கத்தின் அடியிலும் காட்டப்படும் விருப்ப உரை. அடிக்குறிப்பை மறைக்க காலியாக விடவும்.',
        'landing_mode' => 'முகப்புப் பக்கப் பயன்முறை',
        'landing_mode_hint' => 'முதன்மை டொமைனில் பார்வையாளர்கள் காண்பது. பதிவு, செக்அவுட், வலைப்பதிவு மற்றும் சட்டப் பக்கங்கள் எல்லாப் பயன்முறைகளிலும் செயல்படும்.',
        'landing_mode_builtin' => 'உள்ளமைந்த முகப்புப் பக்கம்',
        'landing_mode_builtin_desc' => 'முகப்புப் பக்க மெனுவிலிருந்து நீங்கள் நிர்வகிக்கும் முகப்புப் பக்கத்தைக் காட்டு.',
        'landing_mode_redirect' => 'வெளிப்புற இணையதளத்திற்குத் திருப்பிவிடு',
        'landing_mode_redirect_desc' => 'பார்வையாளர்களை உங்கள் சொந்த இணையதளத்திற்கு அனுப்பவும், எ.கா. வேறு இடத்தில் உருவாக்கப்பட்ட சந்தைப்படுத்தல் தளம்.',
        'landing_mode_disabled' => 'முடக்கப்பட்டது (முகப்புப் பக்கம் இல்லை)',
        'landing_mode_disabled_desc' => 'பொது முகப்புப் பக்கம் இல்லை — முதன்மை டொமைன் உள்நுழைவு அல்லது பதிவுப் பக்கத்தைத் திறக்கும்.',
        'landing_redirect_url' => 'வெளிப்புற இணையதள URL',
        'landing_redirect_url_hint' => 'https:// உடன் தொடங்க வேண்டும். முதன்மை டொமைனுக்கு வரும் பார்வையாளர்கள் இங்கு அனுப்பப்படுவார்கள்.',
        'landing_redirect_status' => 'திருப்பிவிடும் வகை',
        'landing_redirect_302' => '302 — தற்காலிகம் (பரிந்துரைக்கப்படுகிறது)',
        'landing_redirect_301' => '301 — நிரந்தரம்',
        'landing_redirect_status_hint' => 'உலாவிகளும் தேடுபொறிகளும் 301 ஐ நினைவில் வைத்திருக்கும், எனவே ஏற்கெனவே பெற்ற பார்வையாளர்கள் இந்த அமைப்பை மாற்றிய பின்னும் வெளிப்புறத் தளத்திற்கே செல்லக்கூடும். மாற்றம் இறுதியானதாக இல்லாவிட்டால் 302 ஐப் பயன்படுத்தவும்.',
        'landing_disabled_target' => 'முதன்மை டொமைன் காட்டுவது',
        'landing_disabled_login' => 'உள்நுழைவுப் பக்கம்',
        'landing_disabled_signup' => 'பதிவுப் பக்கம்',
        'landing_disabled_target_hint' => 'உள்நுழைவுப் பக்கம்: பார்வையாளர்கள் தங்கள் பணியிட முகவரியை உள்ளிட்டு தங்கள் சொந்த உள்நுழைவுப் பக்கத்திற்கு அழைத்துச் செல்லப்படுவார்கள். பதிவுப் பக்கம்: பணியிடப் பதிவுப் படிவம்.',
        'landing_links' => 'உங்கள் இணையதளத்திற்கான இணைப்புகள்',
        'landing_links_hint' => 'இந்தப் பயன்முறையில் உள்ளமைந்த விலை நிர்ணயப் பிரிவு காட்டப்படாது. பார்வையாளர்கள் உள்நுழைய அல்லது குறிப்பிட்ட திட்டத்திற்குப் பதிவு செய்ய உங்கள் சொந்த இணையதளத்தில் இந்த இணைப்புகளைப் பயன்படுத்தவும்.',
        'landing_link_signin' => 'பணியிட உள்நுழைவு',
        'landing_link_signup' => 'பதிவு',
        'landing_link_plan' => 'பதிவு — :plan',
        'landing_link_copy' => 'இணைப்பை நகலெடு',
        'landing_redirect_loop' => 'இந்த URL இந்தத் தளத்தின் முதன்மைப் பக்கத்தையே சுட்டுகிறது, திருப்பிவிடும் சுழற்சியை உருவாக்கும். வெளிப்புற URL அல்லது குறிப்பிட்ட பாதையைப் பயன்படுத்தவும்.',
        'landing_font' => 'முகப்பு எழுத்துரு',
        'landing_font_default' => 'இயல்புநிலை (வார்ப்புரு எழுத்துரு)',
        'landing_font_hint' => 'அனைத்து முகப்புத் தளவமைப்புகளிலும் பயன்படுத்தப்படும் உடல் எழுத்துரு.',
        'landing_heading_font' => 'தலைப்பு எழுத்துரு',
        'landing_heading_font_default' => 'உடல் எழுத்துருவைப் போலவே',
        'landing_heading_font_hint' => 'தலைப்புகளுக்கான விருப்பத் தனி எழுத்துரு.',
        'custom_font_prefix' => 'தனிப்பயன்',
        'custom_font_name' => 'தனிப்பயன் எழுத்துருப் பெயர்',
        'custom_font_name_placeholder' => 'எ.கா. My Brand Sans',
        'custom_font_file' => 'எழுத்துருக் கோப்பு (woff2, woff, ttf, otf)',
        'custom_font_remove' => 'தனிப்பயன் எழுத்துருவை அகற்று',
        'custom_font_hint' => 'உங்கள் சொந்த எழுத்துருக் கோப்பைப் பதிவேற்றிச் சேமித்து, பின்னர் மேலே உள்ள எழுத்துரு கீழிறக்கங்களிலிருந்து தேர்ந்தெடுக்கவும். கோப்பு பதிவேற்றப்படும்போது பெயர் பயன்படுத்தப்படும்.',
        'custom_font_invalid' => 'எழுத்துரு .woff2, .woff, .ttf அல்லது .otf கோப்பாக இருக்க வேண்டும்.',
        'dashboard_footer_text_placeholder' => 'எ.கா. © 2026 Acme Inc. — அனைத்து உரிமைகளும் பாதுகாக்கப்பட்டவை.',
        'clear_cache_title' => 'தற்காலிகச் சேமிப்பை அழி',
        'clear_cache_desc' => 'உள்ளமைவு, வழிகள், காட்சிகள் மற்றும் தற்காலிகத் தரவு உட்பட மையச் செயலித் தற்காலிகச் சேமிப்பை அழிக்கவும். உள்ளமைவு மாற்றங்கள் அல்லது தளப் புதுப்பிப்புக்குப் பிறகு இதைப் பயன்படுத்தவும்.',
        'clear_central_cache' => 'மையத் தற்காலிகச் சேமிப்பை அழி',
        'email' => 'மின்னஞ்சல்',
        'currency_code_info' => 'பில்லிங், செக்அவுட் மற்றும் விலைப்பட்டியல்களுக்கான இயல்புநிலை நாணயம். உங்கள் கட்டண கேட்வேகள் ஆதரிப்பதுடன் பொருந்த வேண்டும்.',
        'tab_general' => 'பொது',
        'tab_general_desc' => 'செயலிப் பெயர், நாணயம் மற்றும் முக்கிய இயல்புநிலைகள்.',
        'tab_branding' => 'பிராண்டிங்',
        'tab_branding_desc' => 'தளம் முழுவதும் பயன்படுத்தப்படும் லோகோ மற்றும் ஃபேவிகான்.',
        'tab_appearance' => 'தோற்றம்',
        'tab_appearance_desc' => 'தீம் கட்டுப்பாடுகள், டாஷ்போர்டு அடிக்குறிப்பு உரை மற்றும் தெரிவுநிலை விருப்பங்கள்.',
        'tab_company' => 'நிறுவனம்',
        'tab_company_desc' => 'விலைப்பட்டியல்கள், முகப்புப் பக்கம் மற்றும் மின்னஞ்சல்களில் காட்டப்படும் தொடர்பு விவரங்கள்.',
        'tab_tenant' => 'குத்தகைதாரர் அமைப்புகள்',
        'tab_tenant_desc' => 'புதிய குத்தகைதாரர்கள் உருவாக்கப்படும்போது அவர்களுக்குப் பயன்படுத்தப்படும் இயல்புநிலை பிராண்டிங். ஏற்கெனவே உள்ள குத்தகைதாரர்கள் பாதிக்கப்படமாட்டார்கள்.',
        'tenant_intro_title' => 'புதிதாக உருவாக்கப்படும் குத்தகைதாரர்களுக்கான இயல்புநிலைகள்',
        'tenant_intro_text' => 'புதிய குத்தகைதாரர் உருவாக்கப்படும்போது இந்த மதிப்புகள் உள்ளமைந்த "Stocky" இயல்புநிலைகளை மாற்றும். ஏற்கெனவே உள்ள குத்தகைதாரர்கள் தங்கள் தற்போதைய அமைப்புகளை வைத்திருப்பார்கள்.',
        'tenant_app_name' => 'குத்தகைதாரர் செயலிப் பெயர்',
        'tenant_app_name_hint' => 'குத்தகைதாரர் டாஷ்போர்டிலும் உலாவித் தலைப்புப் பட்டையிலும் காட்டப்படும்.',
        'tenant_logo' => 'குத்தகைதாரர் லோகோ',
        'tenant_logo_hint' => 'புதிய குத்தகைதாரர் டாஷ்போர்டுகளுக்கான இயல்புநிலை லோகோவாகப் பயன்படுத்தப்படும். PNG / JPG / SVG / WEBP, அதிகபட்சம் 2 MB.',
        'tenant_favicon' => 'குத்தகைதாரர் ஃபேவிகான்',
        'tenant_favicon_hint' => 'புதிய குத்தகைதாரர்களுக்கு உலாவி தாவல்களில் காட்டப்படும் இயல்புநிலை ஃபேவிகான். PNG / ICO / SVG, அதிகபட்சம் 1 MB.',
        'apply_branding_title' => 'ஏற்கெனவே உள்ள பணியிடங்களுக்குப் பயன்படுத்து',
        'apply_branding_hint' => 'மேலே உள்ள அமைப்புகள் இனி உருவாக்கப்படும் பணியிடங்களுக்கு மட்டுமே பிராண்டிங் செய்யும். முதலில் மாற்றங்களைச் சேமித்து, பின்னர் இதைப் பயன்படுத்தி ஏற்கெனவே உள்ள ஒவ்வொரு பணியிடத்திற்கும் அனுப்பவும். இது ஒவ்வொரு பணியிடத்தின் சொந்த லோகோ, ஃபேவிகான் அல்லது செயலிப் பெயரை மாற்றும்.',
        'apply_branding_upload_first' => '(முதலில் மேலே குத்தகைதாரர் இயல்புநிலையைப் பதிவேற்றவும்)',
        'apply_branding_app_name' => 'செயலிப் பெயர் (":name")',
        'apply_branding_button' => 'ஏற்கெனவே உள்ள அனைத்துப் பணியிடங்களுக்கும் பயன்படுத்து',
        'apply_branding_confirm' => 'தேர்ந்தெடுத்த பிராண்டிங்கை ஏற்கெனவே உள்ள அனைத்துப் பணியிடங்களிலும் மாற்றவா? குத்தகைதாரர்கள் தாங்களே அமைத்த பிராண்டிங் மேலெழுதப்படும்.',
        'apply_branding_save_first' => 'குத்தகைதாரர் அமைப்புகளில் சேமிக்கப்படாத மாற்றங்கள் உள்ளன. முதலில் சேமி என்பதைக் கிளிக் செய்து, பின்னர் பயன்படுத்தவும்.',
        'apply_branding_pick_one' => 'பயன்படுத்த குறைந்தது ஒரு உருப்படியைத் தேர்ந்தெடுக்கவும்.',
        'tenant_company_name' => 'குத்தகைதாரர் நிறுவனப் பெயர்',
        'tenant_company_name_hint' => 'ஒவ்வொரு புதிய குத்தகைதாரரின் அமைப்புகளுக்குள் உள்ள இயல்புநிலை "நிறுவனப் பெயர்".',
        'tenant_email' => 'குத்தகைதாரர் மின்னஞ்சல்',
        'tenant_email_hint' => 'குத்தகைதாரர் அமைப்புகள் வரிசையில் சேமிக்கப்படும் இயல்புநிலை தொடர்பு மின்னஞ்சல்.',
        'tenant_phone' => 'குத்தகைதாரர் தொலைபேசி',
        'tenant_address' => 'குத்தகைதாரர் முகவரி',
        'tenant_currency_code' => 'குத்தகைதாரர் நாணயக் குறியீடு',
        'tenant_currency_code_hint' => 'புதிய குத்தகைதாரர்களுக்கு விதைக்கப்படும் ISO 4217 நாணயக் குறியீடு (எ.கா. USD, EUR, NGN).',
        'tenant_currency_symbol' => 'குத்தகைதாரர் நாணயச் சின்னம்',
        'tenant_default_language' => 'குத்தகைதாரர் இயல்புநிலை மொழி',
        'tenant_default_language_hint' => 'புதிய குத்தகைதாரர்களுக்கான தொடக்க UI மொழி.',
        'tenant_enabled_languages' => 'இயக்கப்பட்ட மொழிகள்',
        'tenant_enabled_languages_hint' => 'புதிய குத்தகைதாரர்களின் மொழித் தேர்வியில் இயக்கப்பட்ட மொழிகள். குத்தகைதாரர் இயல்புநிலை மொழி எப்போதும் இயக்கப்பட்டிருக்கும்; குத்தகைதாரர்கள் இதை பின்னர் அமைப்புகள் → மொழிகளில் மாற்றலாம்.',
