        'tenant_page_title_suffix_hint' => 'உலாவித் தலைப்புப் பட்டையில் பக்கப் பெயருக்குப் பிறகு சேர்க்கப்படும் (எ.கா. "Dashboard | Ultimate Inventory With POS").',
        'tenant_developed_by' => 'உருவாக்கியவர்',
        'tenant_developed_by_hint' => 'குத்தகைதாரர் அடிக்குறிப்பு / விலைப்பட்டியல்களில் காட்டப்படும் குறிப்பு.',
        'remove_tenant_logo' => 'தற்போதைய குத்தகைதாரர் இயல்புநிலை லோகோவை அகற்றவா?',
        'remove_tenant_favicon' => 'தற்போதைய குத்தகைதாரர் இயல்புநிலை ஃபேவிகானை அகற்றவா?',
        'upload_tenant_logo' => 'குத்தகைதாரர் லோகோவைப் பதிவேற்ற கிளிக் செய்யவும்',
        'upload_tenant_favicon' => 'குத்தகைதாரர் ஃபேவிகானைப் பதிவேற்ற கிளிக் செய்யவும்',
        'reserved_subdomains' => 'ஒதுக்கப்பட்ட துணைடொமைன்கள்',
        'reserved_subdomains_hint' => 'பதிவின்போது குத்தகைதாரர்கள் பயன்படுத்த முடியாத துணைடொமைன்கள். ஒரு வரிக்கு ஒன்று (அல்லது கமாவால் பிரித்து) உள்ளிடவும். உங்களுக்குத் தேவையான ஹோஸ்ட்பெயர்களைப் பாதுகாக்க உதவும், எ.கா. admin, server, webmail, mail.',
        'reserved_subdomains_system_note' => 'பொதுவான கணினி துணைடொமைன்கள் (www, admin, api, mail, webmail, server, ftp போன்றவை) இங்கே பட்டியலிடப்படாவிட்டாலும் எப்போதும் ஒதுக்கப்பட்டிருக்கும்.',
        'demo_data_enabled' => 'டெமோ குத்தகைதாரர் ஜெனரேட்டர்',
        'demo_data_enabled_hint' => 'இயக்கப்பட்டால், புதிதாக உருவாக்கப்படும் குத்தகைதாரர்கள் மாதிரி டெமோ தரவுகளால் (வகைகள், இருப்புடன் கூடிய பொருட்கள், வாடிக்கையாளர்கள், விநியோகஸ்தர்கள் மற்றும் எடுத்துக்காட்டு கொள்முதல்கள் & விற்பனைகள்) தானாக நிரப்பப்படும், இதனால் டாஷ்போர்டு மற்றும் அறிக்கைகள் நிரம்பியிருக்கும். தூய்மையான, வெற்று குத்தகைதாரர்களுக்கு முடக்கவும்.',
        'tab_reminders' => 'நினைவூட்டல்கள்',
        'tab_reminders_desc' => 'குத்தகைதாரர்களின் சந்தா அல்லது சோதனை காலாவதியாவதற்கு முன் அனுப்பப்படும் தானியங்கி நினைவூட்டல்கள்.',
