        'reminders_enabled_hint' => 'இயக்கப்பட்டால், குத்தகைதாரர்களின் கட்டணச் சந்தா முடிவதற்கு முன் நினைவூட்டல் பெறுவார்கள்.',
        'reminder_offsets' => 'நினைவூட்டல் நாட்கள் (காலாவதிக்கு முன்)',
