        'trial_reminders_enabled_hint' => 'இயக்கப்பட்டால், இலவசச் சோதனையில் உள்ள குத்தகைதாரர்கள் சோதனை முடிவதற்கு முன் நினைவூட்டல் பெறுவார்கள்.',
        'trial_reminder_offsets' => 'சோதனை நினைவூட்டல் நாட்கள் (சோதனை முடிவதற்கு முன்)',
        'trial_reminder_offsets_hint' => 'நினைவூட்டல் அனுப்ப சோதனை முடிவுத் தேதிக்கு முந்தைய நாட்கள். கமாவால் பிரிக்கவும், எ.கா. 3, 1.',
