        'sms_gateway_hint' => 'SMS நினைவூட்டல்களை அனுப்பப் பயன்படுத்தும் வழங்குநர். நற்சான்றுகள் உங்கள் .env இலிருந்து படிக்கப்படுகின்றன (OTP SMS போலவே). SMS ஐ முடக்க "None" என விடவும்.',
        'sms_gateway_none' => 'எதுவுமில்லை (SMS முடக்கப்பட்டது)',
