        'billing_cycles' => 'வழங்கப்படும் பில்லிங் சுழற்சிகள்',
        'billing_cycles_hint' => 'பதிவின்போதும் திட்டத்தை மாற்றும்போதும் வாடிக்கையாளர்கள் தேர்ந்தெடுக்கக்கூடிய சந்தா காலங்கள். ஒன்றைத் தேர்வுநீக்கினால் அது எங்கும் மறைக்கப்பட்டு செக்அவுட்டில் நிராகரிக்கப்படும். அந்தச் சுழற்சியில் உள்ள சந்தாக்கள் தொடர்ந்து இயங்கும்.',
