        'tab_backup' => 'காப்புப்பிரதி',
        'tab_backup_desc' => 'தரவுத்தளக் காப்புப்பிரதிகளைப் பாதுகாப்பாக உருவாக்கவும், பதிவிறக்கவும், மீட்டெடுக்கவும்.',
        'backup_title' => 'தரவுத்தளக் காப்புப்பிரதிகள்',
        'backup_hint' => 'மையத் தரவுத்தளத்தின் முழு SQL காப்புப்பிரதியை உருவாக்கவும். கோப்புகள் பொது கோப்பகத்திற்கு வெளியே சேமிக்கப்படுகின்றன, அங்கீகரிக்கப்பட்ட சூப்பர் நிர்வாகிகள் மட்டுமே பதிவிறக்க முடியும்.',
        'backup_security_note' => 'காப்புப்பிரதிகள் பொது கோப்புறைக்கு வெளியே வைக்கப்பட்டு, பாதுகாக்கப்பட்ட, அங்கீகரிக்கப்பட்ட பதிவிறக்க இணைப்பு மூலம் வழங்கப்படுகின்றன. பாதைக் கடப்பைத் தடுக்க கோப்புப் பெயர்கள் கண்டிப்பாகச் சரிபார்க்கப்படுகின்றன.',
