        'update_intro_title' => 'உங்கள் செயலியைப் புதுப்பிக்க இந்தப் படிகளைப் பின்பற்றவும்',
        'update_intro_text' => 'உங்கள் நிறுவலில் மாற்றங்களைச் செய்யும் முன் ஒவ்வொரு படியையும் கவனமாகப் பார்க்கவும்.',
        'update_warning_manual_changes' => 'குறிப்பு: குறியீட்டில் கைமுறையாக ஏதேனும் மாற்றங்கள் செய்திருந்தால், அந்த மாற்றங்கள் இழக்கப்படும்.',
        'update_step1_title' => 'படி 1: உங்கள் தரவுத்தளத்தின் காப்புப்பிரதி எடுக்கவும்.',
