        'tips' => 'குறிப்புகள்',
        'tip_categories' => 'வகைகள் இடுகைகளைத் தலைப்புகளாக ஒழுங்கமைக்க உதவுகின்றன (எ.கா. "தயாரிப்புப் புதுப்பிப்புகள்", "வழிகாட்டிகள்", "தொழில்துறைச் செய்திகள்").',
        'tip_slug' => '<strong>ஸ்லக்</strong> URL களில் பயன்படுத்தப்படுகிறது. சிறிய எழுத்துகள், எண்கள் மற்றும் இடைக்கோடுகளை மட்டும் பயன்படுத்தவும்.',
        'tip_sort' => 'குறைந்த வரிசை மதிப்புகள் முதலில் தோன்றும். ஒரே வரிசை உள்ள வகைகள் பெயரால் வரிசைப்படுத்தப்படும்.',
        'ph_category_name' => 'எ.கா. தயாரிப்புப் புதுப்பிப்புகள்',
        'ph_post_title' => 'எ.கா. சிறந்த இருப்பு மேலாண்மைக்கு 10 குறிப்புகள்',
