    'hiw' => [
        'title' => 'இது எப்படி செயல்படுகிறது',
        'subtitle' => 'உங்கள் தற்போதைய ஹோஸ்டிங் பயன்முறைக்கான குத்தகைதாரர் உருவாக்க ஓட்டம்',
        'vps_title' => 'VPS / பிரத்யேக சேவையகம்',
        'vps_desc' => 'முழுத் தானியங்கி உருவாக்கம்',
        'shared_title' => 'பகிரப்பட்ட ஹோஸ்டிங்',
        'shared_desc' => 'தரவுத்தள உள்ளமைவுடன் கைமுறை அங்கீகாரம்',
        'current_mode' => 'தற்போதைய பயன்முறை',
        'vps_section_title' => 'VPS பயன்முறை — தானியங்கி உருவாக்கம்',
        'active' => 'செயலில்',
        'vps_section_desc' => 'VPS பயன்முறையில், தரவுத்தள சேவையகத்தின் மீது கணினிக்கு முழுக் கட்டுப்பாடு உள்ளது. நிர்வாகியின் தலையீடு இல்லாமல் குத்தகைதாரர்கள் தானாக உருவாக்கப்படுவார்கள்.',
        'free_trial_flow' => 'இலவச மற்றும் சோதனைத் திட்டப் பதிவு',
        'paid_flow' => 'கட்டணத் திட்டப் பதிவு',
        'vps_free_step1_title' => 'பயனர் பதிவு செய்கிறார்',
        'vps_free_step1_desc' => 'பயனர் நிறுவனப் பெயர், துணைடொமைன், மின்னஞ்சல் மற்றும் கடவுச்சொல்லுடன் பதிவுப் படிவத்தை நிரப்புகிறார். இலவச அல்லது சோதனைத் திட்டத்தைத் தேர்ந்தெடுக்கிறார்.',
        'vps_free_step2_title' => 'குத்தகைதாரர் "உருவாக்கப்படுகிறது" என உருவாக்கப்படுகிறார்',
        'vps_free_step2_desc' => 'கணினி குத்தகைதாரர் பதிவு, டொமைன் மற்றும் சந்தாவை உடனடியாக உருவாக்குகிறது. நிலை <code>provisioning</code> என அமைக்கப்படும்.',
        'vps_free_step3_title' => 'தானியங்கி தரவுத்தள அமைவு',
        'vps_free_step3_desc' => 'கணினி தானாகப் புதிய MySQL தரவுத்தளத்தை (<code>tenant{uuid}</code>) உருவாக்கி, அனைத்து மைக்ரேஷன்களையும் இயக்கி, இயல்புநிலைத் தரவை விதைத்து, நிர்வாகிப் பயனரை உருவாக்கி, Passport OAuth ஐ நிறுவுகிறது.',
        'vps_free_step4_title' => 'பணியிடம் செயல்படுத்தப்பட்டது',
        'vps_free_step4_desc' => 'நிலை <code>active</code> ஆக மாறும். பயனர் உள்நுழைவு நற்சான்றுகள் காட்டப்பட்டு தங்கள் பணியிடத்திற்குத் திருப்பிவிடப்படுகிறார்.',
        'vps_paid_step1_title' => 'பயனர் பதிவு செய்து பணம் செலுத்துகிறார்',
        'vps_paid_step1_desc' => 'பயனர் பதிவுப் படிவத்தை நிரப்பி, கட்டணத் திட்டத்தைத் தேர்ந்தெடுத்து, உள்ளமைக்கப்பட்ட கட்டண கேட்வே (Stripe, PayPal போன்றவை) மூலம் செக்அவுட்டை முடிக்கிறார்.',
        'vps_paid_step2_title' => 'வெப்ஹூக் மூலம் கட்டணம் சரிபார்க்கப்பட்டது',
        'vps_paid_step2_desc' => 'கட்டண கேட்வே வெற்றிகரமான கட்டணத்தை உறுதிப்படுத்தும் வெப்ஹூக்கை அனுப்புகிறது. கணினி கையொப்பத்தைச் சரிபார்த்து பதிவைச் செலுத்தப்பட்டதாகக் குறிக்கிறது.',
        'vps_paid_step3_title' => 'தானியங்கி உருவாக்கம்',
        'vps_paid_step3_desc' => 'இலவச/சோதனையைப் போலவே: தரவுத்தளம் உருவாக்கப்பட்டு, மைக்ரேஷன்கள் இயக்கப்பட்டு, தரவு விதைக்கப்பட்டு, நிர்வாகிப் பயனர் உருவாக்கப்பட்டு, Passport நிறுவப்படுகிறது. பில்லிங் கட்டணப் பதிவு சேமிக்கப்படுகிறது.',
        'vps_paid_step4_title' => 'பணியிடம் செயல்படுத்தப்பட்டது',
        'vps_paid_step4_desc' => 'நிலை <code>active</code> ஆக மாறும். பயனர் தயாரான பணியிடத்திற்குத் திருப்பிவிடப்படுகிறார். சந்தா உடனடியாகத் தொடங்கும்.',
        'vps_admin_note_label' => 'நிர்வாகியின் பங்கு:',
        'vps_admin_note' => 'VPS பயன்முறையில், நிர்வாகி திட்டங்களை நிர்வகித்து குத்தகைதாரர்களைக் கண்காணித்தால் போதும். கைமுறை அங்கீகாரம் அல்லது தரவுத்தள அமைவு தேவையில்லை.',
        'shared_section_title' => 'பகிரப்பட்ட ஹோஸ்டிங் — கைமுறை அங்கீகாரம்',
        'shared_section_desc' => 'பகிரப்பட்ட ஹோஸ்டிங் பயன்முறையில், கணினி தானாகத் தரவுத்தளங்கள் அல்லது துணைடொமைன்களை உருவாக்க முடியாது (வைல்டுகார்டு DNS இல்லை). ஒவ்வொரு குத்தகைதாரருக்கும் நிர்வாகி ஹோஸ்டிங் பலகையில் கைமுறையாகத் துணைடொமைன் மற்றும் தரவுத்தளத்தை உருவாக்கி, பின்னர் உள்ளமைக்கப்பட்ட நற்சான்றுகளுடன் அங்கீகரிக்க வேண்டும்.',
        'sh_free_step1_title' => 'பயனர் பதிவு செய்கிறார்',
        'sh_free_step1_desc' => 'பயனர் நிறுவனப் பெயர், துணைடொமைன், மின்னஞ்சல் மற்றும் கடவுச்சொல்லுடன் பதிவுப் படிவத்தை நிரப்புகிறார். இலவச அல்லது சோதனைத் திட்டத்தைத் தேர்ந்தெடுக்கிறார்.',
        'sh_free_step2_title' => 'குத்தகைதாரர் "நிலுவையில்" என உருவாக்கப்படுகிறார்',
        'sh_free_step2_desc' => 'கணினி குத்தகைதாரர் பதிவு மற்றும் டொமைனை உருவாக்குகிறது, ஆனால் தரவுத்தளத்தை உருவாக்கவோ எதையும் உருவாக்கவோ <strong>செய்யாது</strong>. நிலை <code>pending</code> என அமைக்கப்படும்.',
        'sh_free_step3_title' => 'மின்னஞ்சல்கள் அனுப்பப்பட்டன',
        'sh_free_step3_desc' => 'புதிய பதிவு குறித்த அறிவிப்பு மின்னஞ்சலை நிர்வாகி பெறுகிறார். பயனர் தங்கள் பதிவு பெறப்பட்டதை உறுதிப்படுத்தும் "மதிப்பாய்வில் உள்ளது" மின்னஞ்சலைப் பெறுகிறார்.',
        'sh_free_step4_title' => 'பயனர் "மதிப்பாய்வில் உள்ளது" பக்கத்தைக் காண்கிறார்',
        'sh_free_step4_desc' => 'பயனர் தங்கள் பதிவு மதிப்பாய்வில் உள்ளது என்றும், அங்கீகரிக்கப்பட்டதும் மின்னஞ்சல் வரும் என்றும் தெரிவிக்கும் பிரத்யேகப் பக்கத்திற்குத் திருப்பிவிடப்படுகிறார்.',
        'sh_free_step5_title' => 'நிர்வாகி ஹோஸ்டிங் பலகையில் துணைடொமைனை உருவாக்குகிறார்',
        'sh_free_step5_desc' => 'நிர்வாகி cPanel / Plesk / ஹோஸ்டிங் பலகையில் உள்நுழைந்து செயலி கோப்பகத்தைச் சுட்டும் துணைடொமைனை (எ.கா. <code>company.yourdomain.com</code>) கைமுறையாக உருவாக்குகிறார். பகிரப்பட்ட ஹோஸ்டிங் வைல்டுகார்டு DNS ஐ ஆதரிக்காததால் இது தேவை.',
        'sh_free_step6_title' => 'நிர்வாகி தரவுத்தளத்தை உருவாக்கி நற்சான்றுகளை உள்ளமைக்கிறார்',
        'sh_free_step6_desc' => 'நிர்வாகி ஹோஸ்டிங் பலகையில் (cPanel > MySQL Databases) புதிய MySQL தரவுத்தளத்தையும் பயனரையும் உருவாக்கி, பின்னர் <a href=":tenants_url">குத்தகைதாரர்கள்</a> அல்லது <a href=":dashboard_url">டாஷ்போர்டு</a> பக்கத்திற்குச் சென்று, <strong>"உள்ளமை & அங்கீகரி"</strong> என்பதைக் கிளிக் செய்து, தரவுத்தள நற்சான்றுகளை (ஹோஸ்ட், பெயர், பயனர், கடவுச்சொல், போர்ட்) நிரப்புகிறார்.',
        'sh_free_step7_title' => 'இணைப்பு சோதிக்கப்பட்டு உருவாக்கப்பட்டது',
        'sh_free_step7_desc' => 'கணினி DB இணைப்பைச் சோதித்து, மைக்ரேஷன்களை இயக்கி, தரவை விதைத்து, நிர்வாகிப் பயனரை உருவாக்கி, Passport ஐ நிறுவுகிறது. ஏதேனும் படி தோல்வியடைந்தால், நிர்வாகி தெளிவான பிழையைக் காண்பார், குத்தகைதாரர் நிலுவையில் இருப்பார்.',
        'sh_free_step8_title' => 'குத்தகைதாரர் செயல்படுத்தப்பட்டு மின்னஞ்சல் அனுப்பப்பட்டது',
        'sh_free_step8_desc' => 'நிலை <code>active</code> ஆக மாறும். பயனர் தங்கள் பணியிட URL மற்றும் உள்நுழைவு இணைப்புடன் அங்கீகார மின்னஞ்சலைப் பெறுகிறார்.',
        'sh_paid_step1_title' => 'பயனர் பதிவு செய்து பணம் செலுத்துகிறார்',
        'sh_paid_step1_desc' => 'பயனர் பதிவுப் படிவத்தை நிரப்பி, கட்டணத் திட்டத்தைத் தேர்ந்தெடுத்து, உள்ளமைக்கப்பட்ட கட்டண கேட்வே மூலம் செக்அவுட்டை முடிக்கிறார்.',
        'sh_paid_step2_title' => 'கட்டணம் சரிபார்க்கப்பட்டது',
        'sh_paid_step2_desc' => 'கட்டண கேட்வே கட்டணத்தை உறுதிப்படுத்துகிறது. பில்லிங் கட்டணப் பதிவு சேமிக்கப்படுகிறது. <strong>தரவுத்தளம் அல்லது உருவாக்கம் இன்னும் நடைபெறாது.</strong>',
        'sh_paid_step3_title' => 'குத்தகைதாரர் "நிலுவையில்" என உருவாக்கப்படுகிறார்',
        'sh_paid_step3_desc' => 'குத்தகைதாரர் பதிவு <code>pending</code> நிலையுடன் உருவாக்கப்படுகிறது. சந்தா <code>pending</code> என அமைக்கப்படுகிறது. நிர்வாகி மற்றும் பயனருக்கு மின்னஞ்சல்கள் அனுப்பப்படுகின்றன.',
        'sh_paid_step4_title' => 'பயனர் "மதிப்பாய்வில் உள்ளது" பக்கத்திற்குத் திருப்பிவிடப்படுகிறார்',
        'sh_paid_step4_desc' => 'கட்டணம் பெறப்பட்டது என்றும் அவர்களின் பணியிடம் நிர்வாகி அங்கீகாரத்திற்காகக் காத்திருக்கிறது என்றும் உறுதிப்படுத்தும் பக்கத்தைப் பயனர் காண்கிறார்.',
        'sh_paid_step5_title' => 'நிர்வாகி துணைடொமைன் மற்றும் தரவுத்தளத்தை உருவாக்குகிறார்',
        'sh_paid_step5_desc' => 'நிர்வாகி ஹோஸ்டிங் பலகையில் (cPanel, Plesk போன்றவை) துணைடொமைனையும் புதிய MySQL தரவுத்தளத்தையும் கைமுறையாக உருவாக்குகிறார்.',
        'sh_paid_step6_title' => 'நிர்வாகி உள்ளமைத்து அங்கீகரிக்கிறார்',
        'sh_paid_step6_desc' => 'நிர்வாகி அங்கீகாரப் படிவத்தில் DB நற்சான்றுகளை உள்ளிட்டு, இணைப்பைச் சோதித்து, அங்கீகரிக்கிறார். கணினி மைக்ரேஷன்களை இயக்கி பணியிடத்தை உருவாக்குகிறது.',
        'sh_paid_step7_title' => 'குத்தகைதாரர் செயல்படுத்தப்பட்டார்',
        'sh_paid_step7_desc' => 'சந்தா செயல்படுத்தப்பட்டது, அங்கீகார மின்னஞ்சல் அனுப்பப்பட்டது, பயனருக்குப் பணியிடம் தயார்.',
        'shared_note_label' => 'முக்கியம்:',
        'shared_note' => 'பகிரப்பட்ட ஹோஸ்டிங் பயன்முறையில், அங்கீகரிக்கும் <em>முன்</em> துணைடொமைன் மற்றும் தரவுத்தளம் <strong>இரண்டையும்</strong> (cPanel, Plesk போன்றவற்றின் மூலம்) நீங்கள் கைமுறையாக உருவாக்க வேண்டும். கணினி தரவுத்தளத்துடன் இணைந்து துணைடொமைனுக்குப் போக்குவரத்தை வழிநடத்தும், ஆனால் பகிரப்பட்ட ஹோஸ்டிங்கில் அவற்றைத் தானாக உருவாக்க முடியாது.',
        'db_security_title' => 'தரவுத்தளப் பாதுகாப்பு',
        'db_sec_encrypt_title' => 'AES-256 குறியாக்கம் செய்யப்பட்ட கடவுச்சொற்கள்',
        'db_sec_encrypt_desc' => 'தரவுத்தளக் கடவுச்சொற்கள் சேமிக்கப்படும் முன் AES-256-CBC (Laravel இன் APP_KEY வழியாக) மூலம் குறியாக்கம் செய்யப்படுகின்றன. மூலக் கடவுச்சொற்கள் ஒருபோதும் சேமிக்கப்படுவதில்லை.',
        'db_sec_isolate_title' => 'தனிமைப்படுத்தப்பட்ட குத்தகைதாரர் தரவுத்தளங்கள்',
        'db_sec_isolate_desc' => 'ஒவ்வொரு குத்தகைதாரருக்கும் தனி தரவுத்தளம் உண்டு. குத்தகைதாரர் உள்நுழையும்போது, கணினி அவர்களின் குறியாக்கம் செய்யப்பட்ட நற்சான்றுகளை ஏற்றி அவர்களின் தனிமைப்படுத்தப்பட்ட தரவுத்தளத்துடன் இணைகிறது.',
        'db_sec_test_title' => 'இணைப்பைச் சோதி',
        'db_sec_test_desc' => 'குத்தகைதாரர் விவரப் பக்கத்தில் "இணைப்பைச் சோதி" பொத்தானைப் பயன்படுத்தி எந்நேரமும் தரவுத்தள நற்சான்றுகளைச் சரிபார்க்கலாம்.',
        'db_sec_migrate_title' => 'மைக்ரேஷன்களை மீண்டும் இயக்கு',
        'db_sec_migrate_desc' => 'மைக்ரேஷன்களை மீண்டும் பயன்படுத்த வேண்டுமெனில் (எ.கா. புதுப்பிப்புக்குப் பிறகு), குத்தகைதாரர் விவரப் பக்கத்தில் "மைக்ரேஷன்களை மீண்டும் இயக்கு" பொத்தானைப் பயன்படுத்தவும்.',
        'lifecycle_title' => 'குத்தகைதாரர் நிலை வாழ்க்கைச் சுழற்சி',
        'status_pending' => 'நிலுவையில்',
        'status_provisioning' => 'உருவாக்கப்படுகிறது',
        'status_active' => 'செயலில்',
        'status_suspended' => 'இடைநிறுத்தப்பட்டது',
        'status_cancelled' => 'ரத்து செய்யப்பட்டது',
        'status_failed' => 'தோல்வி',
        'status_pending_desc' => 'நிர்வாகி அங்கீகாரத்திற்காகக் காத்திருக்கிறது. பகிரப்பட்ட ஹோஸ்டிங் பயன்முறையில் மட்டுமே தோன்றும்.',
        'status_provisioning_desc' => 'தரவுத்தளம் அமைக்கப்படுகிறது, மைக்ரேஷன்கள் இயங்குகின்றன, நிர்வாகிப் பயனர் உருவாக்கப்படுகிறார்.',
        'status_active_desc' => 'முழுமையாக உருவாக்கப்பட்டு அணுகக்கூடியது. குத்தகைதாரர் உள்நுழைந்து பணியிடத்தைப் பயன்படுத்தலாம்.',
        'status_suspended_desc' => 'நிர்வாகியால் தற்காலிகமாக முடக்கப்பட்டது. குத்தகைதாரர் தங்கள் பணியிடத்தை அணுக முடியாது.',
        'status_cancelled_desc' => 'சந்தா ரத்து செய்யப்பட்டது. பணியிடம் இன்னும் இருக்கலாம் ஆனால் அணுகல் கட்டுப்படுத்தப்பட்டுள்ளது.',
        'status_failed_desc' => 'பிழையால் உருவாக்கம் தோல்வியடைந்தது. நிர்வாகி மீண்டும் முயலலாம் அல்லது பிழை விவரங்களைச் சரிபார்க்கலாம்.',
        'faq_title' => 'அடிக்கடி கேட்கப்படும் கேள்விகள்',
        'faq_subtitle' => 'திட்டங்கள், சந்தாக்கள், பில்லிங் மற்றும் குத்தகைதாரர் மேலாண்மை பற்றிய பொதுவான கேள்விகள்.',
        'faq_q1' => 'ஒரு திட்டத்தின் அம்சங்களை மாற்றினால், இது அனைத்துச் சந்தாதாரர்களுக்கும் தானாகப் புதுப்பிக்கப்படுமா?',
        'faq_a1' => '<strong>ஆம், உடனடியாக.</strong> அம்சங்களும் வரம்புகளும் நேரலைத் திட்டத்திற்கு எதிராக நிகழ்நேரத்தில் சரிபார்க்கப்படுகின்றன. கணினி அம்சங்களின் ஸ்னாப்ஷாட்டைச் சேமிப்பதில்லை — குத்தகைதாரர் ஒரு செயலைச் செய்யும் ஒவ்வொரு முறையும் (எ.கா. பொருளை உருவாக்குதல்), மிடில்வேர் அணுகலைச் சரிபார்க்க தற்போதைய திட்டத்தை வினவுகிறது. எனவே ஒரு திட்டத்திலிருந்து அம்சத்தைச் சேர்த்தால் அல்லது அகற்றினால், அந்தத் திட்டத்தில் உள்ள அனைத்துச் சந்தாதாரர்களும் தங்கள் அடுத்த கோரிக்கையிலேயே மாற்றத்தைக் காண்பார்கள்.',
        'faq_q2' => 'ஒரு திட்டத்தின் விலையை உயர்த்தினால், ஏற்கெனவே உள்ள சந்தாதாரர்களுக்குப் புதிய விலை வசூலிக்கப்படுமா?',
        'faq_a2' => '<strong>இல்லை.</strong> குத்தகைதாரர் சந்தா செலுத்தும்போது, அந்த நேரத்தின் விலை அவர்களின் சந்தாப் பதிவில் பூட்டப்படும். திட்ட விலையை மாற்றுவது <strong>புதிய</strong> சந்தாக்களையும் <strong>எதிர்காலப் புதுப்பித்தல்கள் அல்லது திட்ட மாற்றங்களையும்</strong> மட்டுமே பாதிக்கும். ஏற்கெனவே செயலில் உள்ள சந்தாதாரர்கள் புதுப்பிக்கும் வரை அல்லது திட்டத்தை மாற்றும் வரை முதலில் ஒப்புக்கொண்ட தொகையையே தொடர்ந்து செலுத்துவார்கள்.',
        'faq_q3' => 'ஒரு திட்டத்தை நீக்கினால், ஏற்கெனவே உள்ள சந்தாதாரர்கள் தங்கள் கணக்கைத் தொடர்ந்து பயன்படுத்த முடியுமா?',
        'faq_a3' => '<strong>செயலில் சந்தாக்கள் உள்ள திட்டத்தை நீக்க முடியாது.</strong> கணினி நீக்கத்தைத் தடுத்து பிழையைக் காட்டும். இது செயலி மட்டத்திலும் தரவுத்தள மட்டத்திலும் (foreign key கட்டுப்பாடு) செயல்படுத்தப்படுகிறது. ஒரு திட்டத்தை அகற்ற, முதலில் அதன் அனைத்துச் சந்தாதாரர்களையும் வேறு திட்டத்திற்கு மாற்ற வேண்டும், அல்லது அனைத்துச் சந்தாக்களும் முடியும் வரை காத்திருக்க வேண்டும்.',
        'faq_a3_tip' => 'நீக்குவதற்குப் பதிலாக, திட்டத்தை <strong>தனிப்பட்டது</strong> எனக் குறிக்கவும் — அது முகப்புப் பக்கத்திலிருந்து மறைக்கப்படும் ஆனால் ஏற்கெனவே உள்ள சந்தாதாரர்கள் தங்கள் அணுகலைத் தக்கவைப்பார்கள்.',
        'faq_q4' => 'குத்தகைதாரர்கள் தங்கள் திட்டத்தை மேம்படுத்தவோ தரமிறக்கவோ முடியுமா?',
        'faq_a4_p1' => '<strong>ஆம்.</strong> குத்தகைதாரர்கள் தங்கள் பில்லிங் டாஷ்போர்டிலிருந்து எந்நேரமும் திட்டத்தை மாற்றலாம். புதிய திட்டத்தைத் தேர்ந்தெடுக்கும்போது, புதிய திட்ட விலைக்கு புதிய கட்டணம் தேவை. ஏற்கெனவே உள்ள சந்தா புதிய திட்டம், பில்லிங் சுழற்சி மற்றும் தொகையுடன் அதே இடத்தில் புதுப்பிக்கப்படும். கட்டணத்திற்குப் பிறகு புதிய பில்லிங் காலம் உடனடியாகத் தொடங்கும்.',
        'faq_a4_p2' => 'நிர்வாகியாக, சூப்பர் நிர்வாகி பலகையின் <strong>சந்தாக்கள்</strong> பிரிவிலிருந்தும் குத்தகைதாரரின் சந்தாவைக் கைமுறையாக மாற்றலாம்.',
        'faq_q5' => 'அம்ச வரம்புகள் எவ்வாறு செயல்படுகின்றன? (எ.கா., அதிகபட்சப் பொருட்கள், அதிகபட்சப் பயனர்கள்)',
        'faq_a5_intro' => 'ஒவ்வொரு திட்டமும் அதிகபட்சப் பொருட்கள், பயனர்கள், கிடங்குகள், வாடிக்கையாளர்கள் மற்றும் விநியோகஸ்தர்கள் போன்ற வரம்புகளை வரையறுக்கலாம். இந்த வரம்புகள் நிகழ்நேரத்தில் செயல்படுத்தப்படுகின்றன:',
        'faq_a5_li1' => 'குத்தகைதாரர் புதிய பதிவை <strong>உருவாக்க</strong> முயலும்போது, கணினி அவர்களிடம் ஏற்கெனவே எத்தனை உள்ளன என்பதை எண்ணி திட்ட வரம்புடன் ஒப்பிடுகிறது.',
        'faq_a5_li2' => 'வரம்பு எட்டப்பட்டால், செய்தியுடன் உருவாக்கம் தடுக்கப்படும்.',
        'faq_a5_li3' => 'ஏற்கெனவே உள்ள பதிவுகள் <strong>ஒருபோதும் நீக்கப்படாது</strong> — வரம்பைக் குறைத்தால், குத்தகைதாரர்கள் தங்கள் தரவை வைத்திருப்பார்கள் ஆனால் வரம்புக்குக் கீழ் வரும் வரை மேலும் சேர்க்க முடியாது.',
        'faq_a5_li4' => '<code>-1</code> என்ற வரம்பு மதிப்பு <strong>வரம்பற்றது</strong> என்று பொருள்.',
        'faq_q6' => 'சந்தா காலாவதியாகும்போது என்ன நடக்கும்?',
        'faq_a6_intro' => 'கணினி தினமும் தானியங்கிச் சோதனையை இயக்குகிறது:',
        'faq_a6_li1' => '<strong>காலாவதிக்கு 7 நாட்கள் முன்:</strong> புதுப்பிக்க நினைவூட்டும் எச்சரிக்கை மின்னஞ்சல் குத்தகைதாரருக்கு அனுப்பப்படும்.',
        'faq_a6_li2' => '<strong>காலாவதித் தேதியில்:</strong> சந்தா நிலை <code>expired</code> ஆக மாறி அறிவிப்பு மின்னஞ்சல் அனுப்பப்படும்.',
        'faq_a6_li3' => '<strong>காலாவதிக்குப் பிறகு:</strong> குத்தகைதாரர் தங்கள் தரவை இன்னும் காணலாம் ஆனால் அம்சங்களுக்கான அணுகல் உங்கள் உள்ளமைவின் அடிப்படையில் கட்டுப்படுத்தப்படும்.',
        'faq_a6_outro' => 'குத்தகைதாரர் தங்கள் பில்லிங் பக்கத்திலிருந்து புதிய கட்டணம் செலுத்தி எந்நேரமும் புதுப்பிக்கலாம்.',
        'faq_q7' => 'குத்தகைதாரரை இடைநிறுத்தினால் என்ன நடக்கும்?',
        'faq_a7_p1' => '<strong>அனைத்து அணுகலும் உடனடியாகத் தடுக்கப்படும்.</strong> குத்தகைதாரரின் நிலை <code>suspended</code> அல்லது <code>cancelled</code> என அமைக்கப்படும்போது, அவர்களின் பணியிடத்திற்கான ஒவ்வொரு கோரிக்கையும் <strong>403 Forbidden</strong> பிழையைத் தரும். அவர்களால் உள்நுழையவோ API ஐப் பயன்படுத்தவோ செயலியின் எந்தப் பகுதியையும் அணுகவோ முடியாது.',
        'faq_a7_p2' => 'அவர்களின் தரவும் தரவுத்தளமும் அப்படியே இருக்கும். குத்தகைதாரரை மீண்டும் செயல்படுத்தினால் முழு அணுகல் உடனடியாக மீட்கப்படும்.',
        'faq_q8' => 'சோதனைக் காலம் எவ்வாறு செயல்படுகிறது?',
        'faq_a8_intro' => 'ஒரு திட்டத்தில் சோதனை இயக்கப்பட்டிருந்தால்:',
        'faq_a8_li1' => 'பதிவின்போது <strong>கட்டணம் தேவையில்லை</strong> — சோதனையின்போது குத்தகைதாரர் திட்டத்தின் அம்சங்களுக்கு முழு அணுகலைப் பெறுகிறார்.',
        'faq_a8_li2' => 'சோதனைக் காலம் ஒவ்வொரு திட்டத்திற்கும் உள்ளமைக்கப்படுகிறது (எ.கா. 7 நாட்கள், 14 நாட்கள்) அல்லது உலகளாவிய இயல்புநிலைக்குத் திரும்பும்.',
        'faq_a8_li3' => 'சந்தாவில் <code>trial_ends_at</code> தேதி அமைக்கப்படுகிறது. இந்தத் தேதி எதிர்காலத்தில் இருக்கும் வரை, குத்தகைதாரருக்கு முழு அணுகல் உண்டு.',
        'faq_a8_li4' => 'சோதனை காலாவதியாகும்போது, பணியிடத்தைத் தொடர்ந்து பயன்படுத்த குத்தகைதாரர் ஒரு திட்டத்தை வாங்க வேண்டும்.',
        'faq_q9' => 'குத்தகைதாரர் தங்கள் சந்தாவை ரத்து செய்தால் என்ன நடக்கும்?',
        'faq_a9_intro' => 'குத்தகைதாரர் ரத்து செய்யும்போது:',
        'faq_a9_li1' => 'சந்தா நிலை <code>cancelled</code> ஆக மாறும், ஆனால் குத்தகைதாரர் <strong>தற்போதைய பில்லிங் காலம் முடியும் வரை அணுகலைத் தக்கவைப்பார்</strong> (<code>ends_at</code> தேதி).',
        'faq_a9_li2' => 'பில்லிங் காலம் முடிந்ததும், நிலை <code>expired</code> ஆக மாறி அணுகல் கட்டுப்படுத்தப்படும்.',
        'faq_a9_li3' => 'பில்லிங் காலம் முடிவதற்கு முன் எந்நேரமும் குத்தகைதாரர் தங்கள் சந்தாவை <strong>மீண்டும் தொடரலாம்</strong>, இது அதை <code>active</code> நிலைக்கு மீட்டெடுக்கும்.',
        'faq_q10' => 'செயலற்ற அல்லது கைவிடப்பட்ட குத்தகைதாரர் கணக்குகள் எவ்வாறு கையாளப்படுகின்றன?',
        'faq_a10_intro' => 'கணினியில் தினமும் இயங்கும் தானியங்கித் தூய்மைப்படுத்தல் செயல்முறை உள்ளது:',
        'faq_a10_li1' => '<strong>இடைநிறுத்தம்:</strong> சந்தா காலாவதியாகி 7 நாட்களுக்கு மேல் செயலற்றிருக்கும் குத்தகைதாரர்கள் தானாக இடைநிறுத்தப்படுவார்கள்.',
        'faq_a10_li2' => '<strong>நீக்கம்:</strong> இடைநிறுத்தப்பட்ட/ரத்து செய்யப்பட்ட/தோல்வியுற்று 90 நாட்களுக்கு மேல் செயலற்றிருக்கும் குத்தகைதாரர்கள் தானாக நீக்கப்படுவார்கள் (தரவுத்தளம், டொமைன்கள், சந்தாக்கள் மற்றும் கட்டணப் பதிவுகள் அகற்றப்படும்).',
        'faq_a10_li3' => 'செயல்பாடு <code>last_activity_at</code> புலம் மூலம் கண்காணிக்கப்படுகிறது, குத்தகைதாரர் தங்கள் பணியிடத்தை அணுகும்போதெல்லாம் இது புதுப்பிக்கப்படும்.',
        'faq_a10_outro' => '<strong>டாஷ்போர்டு</strong> நலம் எச்சரிக்கைப் பிரிவிலிருந்து செயலற்ற குத்தகைதாரர்களைக் கண்காணிக்கலாம்.',
        'faq_q11' => 'ஒரு திட்டத்தின் வரம்பைக் குறைத்தால், ஏற்கெனவே உள்ள தரவு நீக்கப்படுமா?',
        'faq_a11' => '<strong>இல்லை, ஏற்கெனவே உள்ள தரவு ஒருபோதும் நீக்கப்படாது.</strong> ஒரு திட்டத்தின் பொருள் வரம்பை 500 இலிருந்து 100 ஆகக் குறைத்தால், ஏற்கெனவே 300 பொருட்கள் உள்ள குத்தகைதாரர்கள் 300 ஐயும் வைத்திருப்பார்கள். ஆனால் புதிய வரம்புக்குக் கீழ் வரும் வரை (எ.கா. சிலவற்றை நீக்குவதன் மூலம்) புதிய பொருட்களை உருவாக்க முடியாது. வரம்பு <strong>உருவாக்கத்தை</strong> மட்டுமே கட்டுப்படுத்தும், ஏற்கெனவே உள்ள பதிவுகளை அல்ல.',
        'faq_q12' => 'ஒவ்வொரு குத்தகைதாரரின் தரவும் பிற குத்தகைதாரர்களிடமிருந்து தனிமைப்படுத்தப்பட்டுள்ளதா?',
        'faq_a12' => '<strong>ஆம், முழுமையாக.</strong> ஒவ்வொரு குத்தகைதாரருக்கும் தனிப்பட்ட தரவுத்தளம் உண்டு. குத்தகைதாரர் உள்நுழையும்போது, கணினி குறியாக்கம் செய்யப்பட்ட நற்சான்றுகளைப் பயன்படுத்தி அவர்களின் குறிப்பிட்ட தரவுத்தளத்துடன் இணைகிறது. குத்தகைதாரர்களுக்கிடையே பகிரப்பட்ட தரவு எதுவும் இல்லை — ஒரு குத்தகைதாரர் மற்றொருவரின் பொருட்கள், வாடிக்கையாளர்கள், விற்பனை அல்லது வேறு எந்தத் தரவையும் ஒருபோதும் காண முடியாது.',
        'faq_q13' => 'ஒரே திட்டத்திற்கு மாதாந்திர மற்றும் ஆண்டுதோறும் பில்லிங் இரண்டையும் வழங்க முடியுமா?',
        'faq_a13' => '<strong>ஆம்.</strong> ஒவ்வொரு திட்டமும் மாதாந்திர விலை மற்றும் ஆண்டு விலை இரண்டையும் ஆதரிக்கிறது. திட்டத்தை உருவாக்கும்போது அல்லது திருத்தும்போது இரண்டு விலைகளையும் அமைக்கிறீர்கள். குத்தகைதாரர்கள் செக்அவுட்டின்போது தங்களுக்கு விருப்பமான பில்லிங் சுழற்சியைத் தேர்ந்தெடுக்கிறார்கள். ஆண்டு விலை பொதுவாக 12 மாத மாதாந்திர விலையை விடத் தள்ளுபடி வழங்கும், சேமிப்பு சதவீதம் விலை நிர்ணயப் பக்கத்தில் தானாகக் காட்டப்படும்.',
        'faq_q14' => 'ஒரு திட்டத்தை நீக்காமல் முகப்புப் பக்கத்திலிருந்து மறைக்க முடியுமா?',
        'faq_a14' => '<strong>ஆம்.</strong> திட்டத்தை உருவாக்கும்போது அல்லது திருத்தும்போது <strong>தனிப்பட்டது</strong> எனக் குறிக்கவும். தனிப்பட்ட திட்டங்கள் பொது விலை நிர்ணயப் பக்கத்திலிருந்து மறைக்கப்படும் ஆனால் ஏற்கெனவே உள்ள சந்தாதாரர்களுக்கு முழுமையாகச் செயல்படும். பழைய திட்டங்கள், தனிப்பயன் நிறுவன ஒப்பந்தங்கள் அல்லது நீங்கள் படிப்படியாக நீக்கும் திட்டங்களுக்கு இது பயனுள்ளது.',
        'faq_q15' => 'எந்தக் கட்டண கேட்வேகள் ஆதரிக்கப்படுகின்றன?',
        'faq_a15' => '<strong>அமைப்புகள் > கட்டண கேட்வேகள்</strong> இலிருந்து உள்ளமைக்கக்கூடிய பல கட்டண கேட்வேகளை தளம் ஆதரிக்கிறது. ஒவ்வொரு கேட்வேயும் பாதுகாப்பிற்காக வெப்ஹூக்குகள் வழியாகக் கட்டணங்களைச் செயலாக்குகிறது — குத்தகைதாரர் உருவாக்கப்படும் முன் கட்டணம் சேவையக பக்கத்தில் சரிபார்க்கப்படுகிறது. தேவைக்கேற்ப கேட்வேகளை இயக்கலாம் அல்லது முடக்கலாம்.',
        'quick_actions' => 'விரைவுச் செயல்கள்',
        'quick_pending' => 'நிலுவையில் உள்ள குத்தகைதாரர்களைக் காண்க',
